<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/student_portal.php';$current=tuman_require_role('STUDENT');$db=tuman_database();$assignments=tuman_student_teacher_assignments($db,$current['id']);try{$assignmentId=tuman_student_owned_assignment_id($db,$current['id'],$_GET['assignment_id']??null);$records=tuman_student_attendance($db,$current['id'],$assignmentId);}catch(InvalidArgumentException $e){http_response_code(404);exit('Attendance unavailable.');}tuman_student_page_start('My attendance');
?>
<h1>My attendance</h1><form method="get"><p><label>Teacher <select name="assignment_id"><option value="">All my Teachers</option><?php foreach($assignments as $assignment): ?><option value="<?= (int)$assignment['assignment_id'] ?>"<?= $assignmentId===(int)$assignment['assignment_id']?' selected':'' ?>><?= htmlspecialchars(trim($assignment['first_name'].' '.($assignment['last_name']??'')),ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><button>View</button></p></form><div style="overflow-x:auto"><table><thead><tr><th>Teacher</th><th>Class type</th><th>Date</th><th>Time</th><th>Duration</th><th>Status</th></tr></thead><tbody><?php foreach($records as $record): ?><tr><td><?= htmlspecialchars(trim($record['teacher_first_name'].' '.($record['teacher_last_name']??'')),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($record['batch_name']??'Individual',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($record['session_date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($record['start_time']?substr($record['start_time'],0,5).'–'.substr($record['end_time'],0,5):'—',ENT_QUOTES,'UTF-8') ?></td><td><?= $record['duration_minutes']===null?'—':(int)$record['duration_minutes'].' min' ?></td><td><?= htmlspecialchars($record['status'],ENT_QUOTES,'UTF-8') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($records===[]): ?><p>No attendance records are available.</p><?php endif; ?><?php tuman_student_page_end(); ?>
